function categoryView(category:string){const root=coreContent.value,section=root?.querySelector<HTMLElement>('#minutes-category-'+category);if(!root||!section)return;root.scrollTo({top:root.scrollTop+section.getBoundingClientRect().top-root.getBoundingClientRect().top,behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'});}
