function inspect(t:{kind:'BODY'|'ELEMENT'|'SET';id:string;locatorId?:string}){if(editor.busy.value||editor.loading.value||actions.busy.value)return;const matches=(e:MinutesCurrent['evidence'][number])=>t.kind==='BODY'?e.minutes_revision_id===t.id:e.element_id===t.id;const evidence=value.value?.evidence.find(e=>matches(e)&&(!t.locatorId||e.locator_id===t.locatorId));const directory=t.kind==='SET'&&value.value?.setId===t.id&&!!t.locatorId&&[...(value.value?.sensitive??[]),...(value.value?.background??[])].some(d=>d.locatorIds.includes(t.locatorId!));if(t.kind==='SET'&&!directory||t.locatorId&&!evidence&&!directory){error.value='当前版本没有该目标与来源的关联，请重新核对。';return;}clearInspection();const target={kind:t.kind,id:t.id,locatorId:t.locatorId};selected.value=target;inspectionOpen.value=true;inspectionView.value=evidence||directory?'source':'review';void nextTick(()=>{if(!inspectionOpen.value||selected.value!==target)return;if(inspectDialog.value&&!inspectDialog.value.open)inspectDialog.value.showModal();if(evidence||directory)readInspectionSource(t.locatorId??evidence!.locator_id);});}

